import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// [Start Google Fonts Loader]
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// [End Google Fonts Loader]



export type Spinning3DLogoProps = Record<string, any>;

const StarShape: React.FC<{ color: string; size: number }> = ({ color, size }) => {
  const rays = 12;
  const cx = size / 2;
  const cy = size / 2;
  const strokeWidth = size * 0.08;
  
  const lengths = [
    0.95, 0.85, 0.98, 0.75, 0.92, 0.80, 
    0.95, 0.70, 0.90, 0.85, 0.96, 0.88
  ];

  const lines = lengths.map((len, index) => {
    const angleDeg = (index * 360) / rays;
    const angleRad = (angleDeg - 90) * (Math.PI / 180);
    
    const innerR = size * 0.05; 
    const outerR = (size / 2) * len;

    const x1 = cx + innerR * Math.cos(angleRad);
    const y1 = cy + innerR * Math.sin(angleRad);
    const x2 = cx + outerR * Math.cos(angleRad);
    const y2 = cy + outerR * Math.sin(angleRad);

    return (
      <line
        key={index}
        x1={x1}
        y1={y1}
        x2={x2}
        y2={y2}
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
      />
    );
  });

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ overflow: "visible" }}>
      <circle cx={cx} cy={cy} r={size * 0.15} fill={color} />
      {lines}
    </svg>
  );
};

const Spinning3DLogo: React.FC<Spinning3DLogoProps> = ({
  backgroundColor = "#1A0F0A", 
  titleText = "Meet Claude.",
  durationInSeconds = 8,
  logoColor = "#E6987C", 
  extrusionColor = "#8C4A35", 
  size = 280, 
  depth = 15,
}) => {
  useFontLoader(["Playfair Display"]); 
  
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animation Timing Configuration
  const totalFrames = durationInSeconds * fps;
  const tiltDuration = totalFrames * 0.4; // First 40% to align face-forward
  const glowPeakFrame = totalFrames * 0.5; // Glow peaks halfway
  
  // Phase 1 & 2 Combined: Rotation Logic
  // Start with offset (Y=45) and spin continuously to Y=1080 (3 full rotations from 0)
  // This ensures it starts "already rotating at an angle" and ends "facing forward" (multiple of 360)
  const currentRotY = interpolate(
    frame,
    [0, totalFrames],
    [45, 360 * 3], 
    {
      easing: Easing.out(Easing.poly(3)), // Starts fast, slows down to stop
      extrapolateRight: "clamp",
    }
  );

  // Tilt correction: Start angled, smooth out to 0 (face directly forward)
  const currentRotX = interpolate(
    frame,
    [0, tiltDuration],
    [20, 0],
    {
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.quad),
    }
  );

  const currentRotZ = interpolate(
    frame,
    [0, tiltDuration],
    [10, 0],
    {
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.quad),
    }
  );

  // Glow Animation
  // 0 -> Peak Intensity -> Stabilized Low Intensity
  const glowIntensity = interpolate(
    frame,
    [0, glowPeakFrame, totalFrames],
    [0.1, 1, 0.4], 
    { extrapolateRight: "clamp" }
  );

  const glowBlur = interpolate(
    frame,
    [0, glowPeakFrame, totalFrames],
    [5, 50, 20], 
    { extrapolateRight: "clamp" }
  );

  // Text Reveal: Starts when glow reaches peak
  const textRevealStart = glowPeakFrame;
  const textOpacity = interpolate(
    frame,
    [textRevealStart, textRevealStart + 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const textTranslateY = interpolate(
    frame,
    [textRevealStart, textRevealStart + 30],
    [15, 0], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) }
  );

  // Generate Layers (No useMemo to allow dynamic style injection if needed, though here we use vars)
  // Optimizing: Only the front layer gets the heavy glow filter
  const layerCount = Math.floor(depth); 
  const layers = Array.from({ length: layerCount }).map((_, index) => {
    const zOffset = -index; 
    const isFront = index === 0;
    
    return (
      <div
        key={index}
        style={{
          position: "absolute",
          width: size,
          height: size,
          left: 0,
          top: 0,
          transform: `translateZ(${zOffset}px)`,
          zIndex: layerCount - index,
          // Apply glow only to the front face to create the "light source" effect
          filter: isFront 
            ? `drop-shadow(0px 0px ${glowBlur}px ${logoColor})` 
            : undefined,
          opacity: isFront ? 0.9 + (glowIntensity * 0.1) : 1, // Slight brightness boost
        }}
      >
        <StarShape 
          color={isFront ? logoColor : extrusionColor} 
          size={size} 
        />
      </div>
    );
  });

  return (
    <AbsoluteFill
      style={{
        background: `radial-gradient(circle at 50% 120%, #7d4e3f 0%, ${backgroundColor} 50%, #000000 100%)`,
        perspective: "1200px",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: 40,
          width: "100%",
          maxWidth: 1200,
        }}
      >
        {/* 3D Logo Container */}
        <div
          style={{
            width: size,
            height: size,
            position: "relative",
            transformStyle: "preserve-3d",
            transform: `rotateY(${currentRotY}deg) rotateX(${currentRotX}deg) rotateZ(${currentRotZ}deg)`,
          }}
        >
          {layers}
          
          {/* Back Face (Cap) */}
          <div
            style={{
              position: "absolute",
              width: size,
              height: size,
              left: 0,
              top: 0,
              transform: `translateZ(-${depth}px) rotateY(180deg)`,
              backfaceVisibility: "visible",
            }}
          >
             <StarShape color={logoColor} size={size} />
          </div>
        </div>

        {/* Text Container */}
        <div style={{
          opacity: textOpacity,
          transform: `translateY(${textTranslateY}px)`,
          minWidth: 400, 
        }}>
          <h1
            style={{
              fontFamily: "'Playfair Display', serif",
              fontSize: 100,
              fontWeight: 500,
              color: "#F4F1EA",
              margin: 0,
              lineHeight: 1,
              letterSpacing: "-0.03em",
              textShadow: `0px 0px 20px rgba(0,0,0,0.5)`,
            }}
          >
            {titleText}
          </h1>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default Spinning3DLogo;